cd /Users/eryk.napierala/Projects/dotclaude
SESSION=/Users/eryk.napierala/.claude/projects/-Users-eryk-napierala-Projects-dotclaude/ce5ad95b-63fc-4597-a5b5-cfa6079d241c.jsonl
cp "$SESSION" plans/session-transcript-raw.jsonl
echo "raw copied: $(wc -l < plans/session-transcript-raw.jsonl) lines"

cat > /tmp/extract.mjs <<'EOF'
import fs from "node:fs";

/* ---------- 1. viz source data out of the prototype ---------- */
const html = fs.readFileSync("plans/decision-map.html", "utf8");
const grab = (name) => {
  const m = html.match(new RegExp("const " + name + " = (\\[[\\s\\S]*?\\n\\]);"));
  if (!m) throw new Error("could not find " + name);
  return eval(m[1]);
};
const SRC = grab("SRC"), CARDS = grab("CARDS");

const nodes = [
  ...CARDS.map(c => ({
    id: c.id, kind: "card", title: c.t, why: c.why || null, body: c.d || null,
    status: c.s, who: c.who, noBasis: !!c.nobasis,
  })),
  ...SRC.map(s => ({ id: s.id, kind: "source", title: s.t, url: s.u, tier: s.tier, finding: s.f })),
];
const edges = [];
for (const c of CARDS) {
  if (c.p) edges.push({ from: c.id, to: c.p, type: "refines" });
  for (const d of (c.dep || [])) if (d !== c.p) edges.push({ from: c.id, to: d, type: "depends_on" });
  for (const e of (c.ev  || [])) edges.push({ from: c.id, to: e, type: "supported_by" });
  (c.alt || []).forEach((a, i) => {
    const oid = c.id + ":opt" + i;
    nodes.push({ id: oid, kind: "option", title: a.t, whyNot: a.w });
    edges.push({ from: oid, to: c.id, type: "alternative_to" });
  });
}
const excerpts = [];
for (const c of CARDS) (c.say || []).forEach((q, i) => {
  const xid = c.id + ":ex" + i;
  excerpts.push({ id: xid, kind: "excerpt", speaker: q.w === "you" ? "you" : "agent",
    text: q.q, context: q.a,
    session: "ce5ad95b-63fc-4597-a5b5-cfa6079d241c", msgIndex: null, span: null });
  edges.push({ from: c.id, to: xid, type: "supported_by" });
});
nodes.push(...excerpts);

const out = {
  schema: "decision-map/v1",
  note: "Projection of plans/decision-map.html. msgIndex and span are null: quotes were hand-written, not extracted. See plans/decision-map-structure.md.",
  producedAt: fs.statSync("plans/decision-map.html").mtime.toISOString(),
  counts: {
    cards: CARDS.length, sources: SRC.length,
    options: nodes.filter(n => n.kind === "option").length,
    excerpts: excerpts.length, edges: edges.length,
  },
  nodes, edges,
};
fs.writeFileSync("plans/decision-map-data.json", JSON.stringify(out, null, 2));
console.log("decision-map-data.json:", JSON.stringify(out.counts));

/* ---------- 2. readable transcript ---------- */
const lines = fs.readFileSync("plans/session-transcript-raw.jsonl", "utf8").split("\n").filter(Boolean);
let md = "# Session transcript — pipeline design\n\n" +
  "Session `ce5ad95b-63fc-4597-a5b5-cfa6079d241c`, project `dotclaude`, 2026-08-31 to 2026-09-01.\n\n" +
  "Readable projection. Tool calls are collapsed to one line. The full record with every tool\n" +
  "input and output is in `session-transcript-raw.jsonl`.\n\n---\n\n";
let n = 0;
for (const line of lines) {
  let e; try { e = JSON.parse(line); } catch { continue; }
  if (e.type !== "user" && e.type !== "assistant") continue;
  const c = e.message?.content;
  if (!c) continue;
  const blocks = Array.isArray(c) ? c : [{ type: "text", text: c }];
  const parts = [];
  for (const b of blocks) {
    if (b.type === "text" && b.text?.trim()) parts.push(b.text.trim());
    else if (b.type === "tool_use") parts.push("`[tool: " + b.name + "]`");
    else if (b.type === "tool_result") parts.push("`[tool result]`");
    else if (b.type === "thinking") parts.push("`[thinking]`");
    else if (b.type === "image") parts.push("`[image attached]`");
  }
  const body = parts.join("\n\n").trim();
  if (!body || /^(`\[tool[^\]]*\]`\s*)+$/.test(body)) continue;
  if (body.startsWith("<system-reminder>") || body.startsWith("<local-command")) continue;
  md += "## " + (++n) + ". " + (e.type === "user" ? "Eryk" : "Claude") + "\n\n" + body + "\n\n---\n\n";
}
fs.writeFileSync("plans/session-transcript.md", md);
console.log("session-transcript.md:", n, "turns,", Math.round(md.length/1024), "KB");
EOF
node /tmp/extract.mjs
